impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> UlFieldBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_field_name(&mut self, field_name: flatbuffers::WIPOffset<&'b str>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(UlField::VT_FIELD_NAME, field_name);
    }
    #[inline]
    pub fn add_display_name(&mut self, display_name: flatbuffers::WIPOffset<&'b str>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(UlField::VT_DISPLAY_NAME, display_name);
    }
    #[inline]
    pub fn add_component_data_type(&mut self, component_data_type: ComponentData) {
        self.fbb_.push_slot::<ComponentData>(
            UlField::VT_COMPONENT_DATA_TYPE,
            component_data_type,
            ComponentData::NONE,
        );
    }
    #[inline]
    pub fn add_component_data(
        &mut self,
        component_data: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>,
    ) {
        self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(
            UlField::VT_COMPONENT_DATA,
            component_data,
        );
    }
    #[inline]
    pub fn add_flags(&mut self, flags: u32) {
        self.fbb_.push_slot::<u32>(UlField::VT_FLAGS, flags, 0);
    }
    #[inline]
    pub fn add_unit(&mut self, unit: FieldUnit) {
        self.fbb_
            .push_slot::<FieldUnit>(UlField::VT_UNIT, unit, FieldUnit::U_INVALID);
    }
    #[inline]
    pub fn add_field_type(&mut self, field_type: UlFieldType) {
        self.fbb_.push_slot::<UlFieldType>(
            UlField::VT_FIELD_TYPE,
            field_type,
            UlFieldType::FT_UNKNOWN,
        );
    }
    #[inline]
    pub fn add_description(&mut self, description: flatbuffers::WIPOffset<&'b str>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(UlField::VT_DESCRIPTION, description);
    }
    #[inline]
    pub fn add_breakdown_display_name(
        &mut self,
        breakdown_display_name: flatbuffers::WIPOffset<&'b str>,
    ) {
        self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(
            UlField::VT_BREAKDOWN_DISPLAY_NAME,
            breakdown_display_name,
        );
    }
    #[inline]
    pub fn add_default(&mut self, default: flatbuffers::WIPOffset<ValueInstance<'b>>) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<ValueInstance>>(
                UlField::VT_DEFAULT,
                default,
            );
    }
    #[inline]
    pub fn add_storage_type_type(&mut self, storage_type_type: Type) {
        self.fbb_
            .push_slot::<Type>(UlField::VT_STORAGE_TYPE_TYPE, storage_type_type, Type::NONE);
    }
    #[inline]
    pub fn add_storage_type(
        &mut self,
        storage_type: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>,
    ) {
        self.fbb_
            .push_slot_always::<flatbuffers::WIPOffset<_>>(UlField::VT_STORAGE_TYPE, storage_type);
    }
    #[inline]
    pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> UlFieldBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        UlFieldBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }
    #[inline]
    pub fn finish(self) -> flatbuffers::WIPOffset<UlField<'a>> {
        let o = self.fbb_.end_table(self.start_);
        flatbuffers::WIPOffset::new(o.value())
    }
}

