impl core::fmt::Debug for Metadata<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut ds = f.debug_struct("Metadata");
        ds.field("display_name", &self.display_name());
        ds.field("description", &self.description());
        ds.field("fields", &self.fields());
        ds.field("summary", &self.summary());
        ds.field("dataset_category", &self.dataset_category());
        ds.field("field_relationships", &self.field_relationships());
        ds.field("source", &self.source());
        ds.field("geometry_source_type", &self.geometry_source_type());
        match self.geometry_source_type() {
            GeometrySource::NoGeometry => {
                if let Some(x) = self.geometry_source_as_no_geometry() {
                    ds.field("geometry_source", &x)
                } else {
                    ds.field(
                        "geometry_source",
                        &"InvalidFlatbuffer: Union discriminant does not match value.",
                    )
                }
            }
            GeometrySource::DatacatalogGeometry => {
                if let Some(x) = self.geometry_source_as_datacatalog_geometry() {
                    ds.field("geometry_source", &x)
                } else {
                    ds.field(
                        "geometry_source",
                        &"InvalidFlatbuffer: Union discriminant does not match value.",
                    )
                }
            }
            GeometrySource::WorldGraphGeometry => {
                if let Some(x) = self.geometry_source_as_world_graph_geometry() {
                    ds.field("geometry_source", &x)
                } else {
                    ds.field(
                        "geometry_source",
                        &"InvalidFlatbuffer: Union discriminant does not match value.",
                    )
                }
            }
            _ => {
                let x: Option<()> = None;
                ds.field("geometry_source", &x)
            }
        };
        ds.field("area_selection", &self.area_selection());
        ds.field(
            "do_not_filter_geometry_by_viewport",
            &self.do_not_filter_geometry_by_viewport(),
        );
        ds.field("entity_ty", &self.entity_ty());
        ds.field("update_cadence", &self.update_cadence());
        ds.field(
            "location_description_field",
            &self.location_description_field(),
        );
        ds.field("promoted_metrics", &self.promoted_metrics());
        ds.field(
            "visualize_in_explore_fields",
            &self.visualize_in_explore_fields(),
        );
        ds.finish()
    }
}
